INSERT INTO t_permission(name,code,type,parent_id,path,method,description,status,sort,create_time,update_time,del_flag) SELECT '查询模型调用额度','ai:quota:read','api',0,'/v1/agent-console/quota','GET','查询模型调用额度','active',100,NOW(),NOW(),0 WHERE NOT EXISTS(SELECT 1 FROM t_permission WHERE method='GET' AND path='/v1/agent-console/quota' AND code='ai:quota:read' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r JOIN t_permission p ON p.method='GET' AND p.path='/v1/agent-console/quota' AND p.code='ai:quota:read' AND p.del_flag=0 AND p.status='active' WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
